<?php require_once '../config.php'; login_required('admin'); $rows=mysqli_query($conn,'SELECT category,COUNT(*) total FROM books GROUP BY category ORDER BY category');?><!doctype html><html><head><title>Categories</title><link rel="stylesheet" href="../assets/css/admin/categories.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><h1>Categories</h1><div class="panel"><table><tr><th>Category</th><th>Books</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=e($r['category'])?></td><td><?=$r['total']?></td></tr><?php endwhile;?></table></div></main></div></body></html>
